module SPI_Shift_register (
    // Global signals
    input  wire        PCLK,             // APB clock
    input  wire        PRESET_n,         // Active-low reset
 
    // Control signals
    input  wire        ss_i,             // Slave Select (active low)
    input  wire        send_data_i,      // Load shift register with data_mosi_i
    input  wire        lsbfe_i,          // 1 = LSB first, 0 = MSB first
    input  wire        cpha_i,           // SPI Clock Phase
    input  wire        cpol_i,           // SPI Clock Polarity
 
    // SPI clock edges (generated by Baud-rate generator)
    input  wire        miso_receive_sclk_i,   // Sample edge for MISO
    input  wire        miso_receive_sclk0_i,  // Complementary sample edge
    input  wire        mosi_send_sclk_i,      // Shift edge for MOSI
    input  wire        mosi_send_sclk0_i,     // Complementary shift edge
 
    // Data
    input  wire [7:0]  data_mosi_i,      // Parallel data to transmit
    input  wire        miso_i,           // Serial input from slave
    input  wire        receive_data_i,   // Enable MISO capture
 
    // Outputs
    output reg         mosi_o,           // Serial output to slave
    output reg  [7:0]  data_miso_o       // Parallel received data
);
 
    // -------------------------------------------------------
    // Internal registers
    // -------------------------------------------------------
    reg [7:0]  shift_reg;         // Main shift register
    reg [2:0]  count;             // Bit counter  (0-7, MSB first)
    reg [2:0]  count1;            // Bit counter  (7-0, LSB first)
 
    // -------------------------------------------------------
    // 1. Load / hold the shift register
    // -------------------------------------------------------
    always @(posedge PCLK or negedge PRESET_n) begin
        if (!PRESET_n)
            shift_reg <= 8'h00;
        else if (send_data_i)
            shift_reg <= data_mosi_i;
        else
            shift_reg <= shift_reg;
    end
 
    // -------------------------------------------------------
    // 2. Drive MOSI – count and count1 track bit position
    //    count  : increments from 0 → 7 (MSB-first index)
    //    count1 : decrements from 7 → 0 (LSB-first index)
    // -------------------------------------------------------
    always @(posedge PCLK or negedge PRESET_n) begin
        if (!PRESET_n) begin
            mosi_o  <= 1'b0;
            count   <= 3'd0;
            count1  <= 3'd7;
        end
        else begin
            // Active only when slave selected
            if (!ss_i) begin
                // --- CPHA=0: shift on rising SCLK edge ---
                if (!cpha_i) begin
                    if (mosi_send_sclk_i) begin
                        if (!lsbfe_i) begin
                            // MSB first
                            mosi_o <= shift_reg[7 - count];
                            count  <= (count == 3'd7) ? 3'd0 : count + 1'b1;
                            count1 <= 3'd7;
                        end
                        else begin
                            // LSB first
                            mosi_o <= shift_reg[count1];
                            count1 <= (count1 == 3'd0) ? 3'd7 : count1 - 1'b1;
                            count  <= 3'd0;
                        end
                    end
                end
                // --- CPHA=1: shift on falling SCLK edge ---
                else begin
                    if (mosi_send_sclk0_i) begin
                        if (!lsbfe_i) begin
                            // MSB first
                            mosi_o <= shift_reg[7 - count];
                            count  <= (count == 3'd7) ? 3'd0 : count + 1'b1;
                            count1 <= 3'd7;
                        end
                        else begin
                            // LSB first
                            mosi_o <= shift_reg[count1];
                            count1 <= (count1 == 3'd0) ? 3'd7 : count1 - 1'b1;
                            count  <= 3'd0;
                        end
                    end
                end
            end
            else begin
                // De-selected: drive MOSI idle, reset counters
                mosi_o <= 1'b0;
                count  <= 3'd0;
                count1 <= 3'd7;
            end
        end
    end
 
    // -------------------------------------------------------
    // 3. Sample MISO into data_miso_o shift register
    // -------------------------------------------------------
    always @(posedge PCLK or negedge PRESET_n) begin
        if (!PRESET_n)
            data_miso_o <= 8'h00;
        else begin
            if (!ss_i && receive_data_i) begin
                // CPHA=0 : sample on rising SCLK
                if (!cpha_i) begin
                    if (miso_receive_sclk_i) begin
                        if (!lsbfe_i)
                            // MSB first: shift left, new bit at LSB
                            data_miso_o <= {data_miso_o[6:0], miso_i};
                        else
                            // LSB first: shift right, new bit at MSB
                            data_miso_o <= {miso_i, data_miso_o[7:1]};
                    end
                end
                // CPHA=1 : sample on falling SCLK
                else begin
                    if (miso_receive_sclk0_i) begin
                        if (!lsbfe_i)
                            data_miso_o <= {data_miso_o[6:0], miso_i};
                        else
                            data_miso_o <= {miso_i, data_miso_o[7:1]};
                    end
                end
            end
        end
    end
 
endmodule
 